typedef float rational_t;
typedef unsigned long uint64;

class pstring
{
  uint64 pchunk[4];
  void pack_string(const char *);
public:
  pstring(const char *target_string)
  {
    pack_string(target_string);
  }

  bool operator==(const pstring &check_me) const
  {
    for (unsigned i=0; i<4; ++i)
    {
      if (pchunk[i] != check_me.pchunk[i])
        return false;
    }
    return true;
  }
};

class entity;

class generic_interface
{
public:
  virtual ~generic_interface();
};

class entity_interface : public generic_interface
{
protected:
  entity *my_entity;
};

class ai_interface : public entity_interface
{
protected:
  unsigned int flags;

public:
  enum
  {
    _AI_ACTIVE = 0x00000001,
    _AI_COSMETIC = 0x00000080
  };

  inline void set_flag(unsigned int f, bool val = true)
  {
    if(val) flags |= f; else flags &= ~f;
  }

  inline void set_active(bool a) { set_flag(_AI_ACTIVE, a); }
  inline void set_cosmetic(bool a) { set_flag(_AI_COSMETIC, a); }

  bool set_ifc_num(const pstring &att, rational_t val);
};

__asm__(".equ pack_string__7pstringPCc,0x003354D0");

#define IFC_INTERNAL_FUNC_MACRO(a,b) { static pstring pstring_func(a); if(att == pstring_func) { b; return(true); } }

bool ai_interface::set_ifc_num(const pstring &att, rational_t val)
{
  IFC_INTERNAL_FUNC_MACRO("AI_ACTIVE", set_active(val != 0.0f));
  IFC_INTERNAL_FUNC_MACRO("AI_COSMETIC", set_cosmetic(val != 0.0f));
